// Wire protocol v2 (docs/remote-contract.md §3), generated by hand from
// pkg/remote/wire/wire.go and the fixtures in pkg/remote/wire/testdata.
// Every decoder builds a fresh value holding only the fields the contract
// declares, so protocol.test.ts can re-encode each fixture and compare bytes
// the way the Go test does: an undeclared field is dropped and fails the
// comparison, a missing required field fails the decode.

export const PROTOCOL = 2;

export const MAX_FRAME_BYTES = 12 << 20;
export const MAX_IN_FLIGHT = 8;
export const MAX_PAGE_LIMIT = 100;

// Close codes the client acts on (§3.1); 4408 slow consumer is an ordinary
// reconnect and needs no name here.
export const CLOSE_BAD_HELLO = 4400;
export const CLOSE_TOKEN_INVALID = 4401;
export const CLOSE_REVOKED = 4403;
export const CLOSE_RATE_LIMITED = 4429;

// The one error code the client branches on (R1); the others reach the
// person as the server's message.
export const CODE_TOKEN_INVALID = "token_invalid";

// ---- decoders -------------------------------------------------------------

export type Decoder<T> = (v: unknown) => T | null;

export function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

export const str: Decoder<string> = (v) => (typeof v === "string" ? v : null);
export const int: Decoder<number> = (v) =>
  typeof v === "number" && Number.isInteger(v) ? v : null;
export const bool: Decoder<boolean> = (v) => (typeof v === "boolean" ? v : null);
// Timestamps are RFC 3339 strings; the client keeps them as strings.
export const time: Decoder<string> = (v) =>
  typeof v === "string" && !Number.isNaN(Date.parse(v)) ? v : null;
// Raw JSON (req params, ev payloads): anything but undefined.
export const raw: Decoder<unknown> = (v) => (v === undefined ? null : v);

export function oneOf<const T extends readonly string[]>(values: T): Decoder<T[number]> {
  return (v) => (typeof v === "string" && values.includes(v) ? (v as T[number]) : null);
}

// Go marshals a nil slice or map as null; the client reads that as empty.
export function list<T>(d: Decoder<T>): Decoder<T[]> {
  return (v) => {
    if (v === null) return [];
    if (!Array.isArray(v)) return null;
    const out: T[] = [];
    for (const item of v) {
      const x = d(item);
      if (x === null) return null;
      out.push(x);
    }
    return out;
  };
}

function dict<T>(d: Decoder<T>): Decoder<Record<string, T>> {
  return (v) => {
    if (v === null) return {};
    if (!isRecord(v)) return null;
    const out: Record<string, T> = {};
    for (const [k, item] of Object.entries(v)) {
      const x = d(item);
      if (x === null) return null;
      out[k] = x;
    }
    return out;
  };
}

type Shape = Record<string, Decoder<unknown>>;
type Out<D> = D extends Decoder<infer T> ? T : never;
type Req<S extends Shape> = { [K in keyof S]: Out<S[K]> };
type Opt<S extends Shape> = { [K in keyof S]?: Out<S[K]> };

// An object with the required fields of `req` and the optional ones of
// `opt`. Optional fields are those Go writes with omitempty: absent or typed.
export function object<R extends Shape, O extends Shape>(req: R, opt: O): Decoder<Req<R> & Opt<O>> {
  return (v) => {
    if (!isRecord(v)) return null;
    const out: Record<string, unknown> = {};
    for (const [k, d] of Object.entries(req)) {
      const x = d(v[k]);
      if (x === null) return null;
      out[k] = x;
    }
    for (const [k, d] of Object.entries(opt)) {
      const field = v[k];
      if (field === undefined) continue;
      const x = d(field);
      if (x === null) return null;
      out[k] = x;
    }
    return out as Req<R> & Opt<O>;
  };
}

const empty: Decoder<Record<string, never>> = (v) => (isRecord(v) ? {} : null);

// ---- entities ---------------------------------------------------------------

export type Mode = "plan" | "ask" | "yolo";
export const MODES: readonly Mode[] = ["plan", "ask", "yolo"];
export const decodeMode: Decoder<Mode> = oneOf(MODES);
export const isMode = (v: unknown): v is Mode => decodeMode(v) !== null;

// "answer" answers a question approval (with answers); "deny" declines it.
export type Decision = "allow" | "allow_session" | "deny" | "answer";
const decodeDecision = oneOf(["allow", "allow_session", "deny", "answer"] as const);

// "question": an agent asks the person something (Approval.questions).
