export interface ReqFrame {
  t: "req";
  id: string;
  m: string;
  p?: unknown;
}

export const decodeReqFrame: Decoder<ReqFrame> = object(
  { t: oneOf(["req"] as const), id: str, m: str },
  { p: raw },
);

export interface WireError {
  code: string;
  msg: string;
}

export const decodeWireError: Decoder<WireError> = object({ code: str, msg: str }, {});

export interface ResOkFrame {
  t: "res";
  id: string;
  ok: true;
  r?: unknown;
}

export interface ResErrFrame {
  t: "res";
  id: string;
  ok: false;
  err: WireError;
}

export type ResFrame = ResOkFrame | ResErrFrame;

const decodeResShape = object(
  { t: oneOf(["res"] as const), id: str, ok: bool },
  { r: raw, err: decodeWireError },
);

// Go writes an empty RawMessage as null; the phone reads that as absent.
function nullToAbsent(v: unknown, key: string): unknown {
  if (!isRecord(v) || v[key] !== null) return v;
  const { [key]: _null, ...rest } = v;
  return rest;
}

export const decodeResFrame: Decoder<ResFrame> = (v) => {
  const f = decodeResShape(nullToAbsent(v, "r"));
  if (f === null) return null;
  if (f.ok) {
    const out: ResOkFrame = { t: "res", id: f.id, ok: true };
    if (f.r !== undefined) out.r = f.r;
    return out;
  }
  if (f.err === undefined) return null;
  return { t: "res", id: f.id, ok: false, err: f.err };
};

export interface EvFrame {
  t: "ev";
  seq: number;
  e: string;
  p?: unknown;
}

const decodeEvShape = object({ t: oneOf(["ev"] as const), seq: int, e: str }, { p: raw });

export const decodeEvFrame: Decoder<EvFrame> = (v) => decodeEvShape(nullToAbsent(v, "p"));

export interface ResyncFrame {
  t: "resync";
}

export const decodeResyncFrame: Decoder<ResyncFrame> = object(
  { t: oneOf(["resync"] as const) },
  {},
);

export type ServerFrame = WelcomeFrame | ResFrame | EvFrame | ResyncFrame;

export const FRAME_TYPES = ["hello", "welcome", "req", "res", "ev", "resync"] as const;

// Frames the phone receives. Unknown types decode to null (dropped with a
// warning by the caller), never thrown.
export function decodeServerFrame(v: unknown): ServerFrame | null {
  if (!isRecord(v)) return null;
  switch (v["t"]) {
    case "welcome":
      return decodeWelcomeFrame(v);
    case "res":
      return decodeResFrame(v);
    case "ev":
      return decodeEvFrame(v);
    case "resync":
      return decodeResyncFrame(v);
    default:
      return null;
  }
}

export function parseServerFrame(text: string): ServerFrame | null {
  let v: unknown;
  try {
    v = JSON.parse(text);
  } catch {
    return null;
  }
  return decodeServerFrame(v);
}

