// Mirror of wire.Fixtures(): every fixture file and the decoder that must
// accept it. protocol.test.ts fails on a missing, unregistered or
// non-canonical file, and on a decode that is not byte-equal after sorting.
export const FIXTURES: ReadonlyArray<[name: string, decode: Decoder<unknown>]> = [
  ["frame_hello", decodeHelloFrame],
  ["frame_welcome", decodeWelcomeFrame],
  ["frame_req", decodeReqFrame],
  ["frame_res", decodeResFrame],
  ["frame_res_err", decodeResFrame],
  ["frame_ev", decodeEvFrame],
  ["frame_resync", decodeResyncFrame],

  ["entity_session", decodeSession],
  ["entity_message", decodeMessage],
  ["entity_approval", decodeApproval],
  ["entity_approval_edit", decodeApproval],
  ["entity_approval_question", decodeApproval],
  ["entity_queued_item", decodeQueuedItem],
  ["entity_agent_line", decodeAgentLine],
  ["entity_model_choice", decodeModelChoice],
  ["entity_changed_file", decodeChangedFile],
  ["entity_device", decodeDevice],
  ["entity_theme", decodeTheme],

  ...EVENT_NAMES.map((e): [string, Decoder<unknown>] => [
    `event_${e}`,
    EVENT_DECODERS[e] as Decoder<unknown>,
  ]),

  ...METHOD_NAMES.flatMap(
    (m): Array<[string, Decoder<unknown>]> => [
      [`req_${m}`, METHODS[m].req as Decoder<unknown>],
      [`res_${m}`, METHODS[m].res as Decoder<unknown>],
    ],
  ),
  ["req_approvals.answer_question", decodeApprovalsAnswerParams],

  ["http_health", decodeHealth],
  ["http_pair_request", decodePairRequest],
  ["http_pair_response", decodePairResponse],
  ["http_pair_error", decodePairError],
];
